/* Parse start/end range if any. Do this before looking up the key so
 * that syntax errors are reported even for non existing keys. */
if (c->argc == 4 || c->argc == 5 || c->argc == 6) {
    if (getLongLongFromObjectOrReply(c,c->argv[3],&start,NULL) != C_OK)
        return;
    if (c->argc == 6) {
        if (!strcasecmp(c->argv[5]->ptr,"bit")) isbit = 1;
        else if (!strcasecmp(c->argv[5]->ptr,"byte")) isbit = 0;
        else {
            addReplyErrorObject(c,shared.syntaxerr);
            return;
        }
    }
    if (c->argc >= 5) {
        if (getLongLongFromObjectOrReply(c,c->argv[4],&end,NULL) != C_OK)
            return;
        end_given = 1;
    }
} else if (c->argc != 3) {
    /* Syntax error. */
    addReplyErrorObject(c,shared.syntaxerr);
    return;
}

/* If the key does not exist, from our point of view it is an infinite
 * array of 0 bits. If the user is looking for the first clear bit return 0,
 * If the user is looking for the first set bit, return -1. */
if ((o = lookupKeyRead(c->db,c->argv[1])) == NULL) {
    addReplyLongLong(c, bit ? -1 : 0);
    return;
}
if (checkType(c,o,OBJ_STRING)) return;
p = loadBitStringView(&view, o, llbuf);
strlen = view.len;

/* Compute the range to search now that the string length is known. */
if (c->argc == 4 || c->argc == 5 || c->argc == 6) {
    long long totlen = strlen;
    /* Make sure we will not overflow */
    serverAssert(totlen <= LLONG_MAX >> 3);
    if (c->argc < 5) {
        if (isbit) end = (totlen<<3) + 7;
        else end = totlen-1;
